export function AdaptiveLayout({
  width = {{width}},
  showGuide = {{showGuide}},
  gap = {{gap}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 660 }}>
      {showGuide && <p style={{ fontSize: 11, color: "#241430aa", margin: "0 0 8px" }}>Jumps between 3 fixed configs: 1-col below 260px, 2-col below 460px, 3-col above</p>}
      <div style={{ width, maxWidth: "100%", containerType: "inline-size", background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, padding: 14, boxSizing: "border-box" }}>
        <div className="grid" style={{ display: "grid", gridTemplateColumns: "1fr", gap }}>
          <span style={{ height: 46, borderRadius: 8, background: accent }} />
          <span style={{ height: 46, borderRadius: 8, background: accent }} />
          <span style={{ height: 46, borderRadius: 8, background: accent }} />
        </div>
      </div>
      <style>{`
        @container (min-width: 260px) { .grid { grid-template-columns: 1fr 1fr; } }
        @container (min-width: 460px) { .grid { grid-template-columns: 1fr 1fr 1fr; } }
      `}</style>
    </div>
  );
}
